//! WP 1.4 oracle: isolate the finite-burn loss within 1% of an independent
//! analytical-integral reference. The CSV is generated by
//! `tools/astro-oracle/finite_burn_loss_scipy.py` (SciPy DOP853), which carries
//! the steering and gravity loss integrals as extra ODE states rather than
//! reconstructing them from this crate's spline.
use odd_astro::{
    finite_burn::{isolate_finite_burn, BurnLoss},
    integrator::Options,
    perturb::burn::Burn,
    spline::Keyframe,
};

const MU: f64 = 3.986_004_418e14;
const CSV: &str = include_str!("../../../data/oracles/finite-burn-loss.csv");

struct Case {
    name: String,
    radius: f64,
    mass: f64,
    thrust: f64,
    isp: f64,
    delta_v: f64,
    duration: f64,
    angle: f64,
    ideal: f64,
    steering: f64,
    gravity: f64,
    deficit: f64,
}

fn cases() -> Vec<Case> {
    CSV.lines()
        .skip(1)
        .filter(|l| !l.trim().is_empty())
        .map(|line| {
            let f: Vec<&str> = line.split(',').collect();
            let p = |i: usize| f[i].parse::<f64>().unwrap();
            Case {
                name: f[0].to_string(),
                radius: p(1),
                mass: p(2),
                thrust: p(3),
                isp: p(4),
                delta_v: p(5),
                duration: p(6),
                angle: p(7),
                ideal: p(8),
                steering: p(9),
                gravity: p(10),
                deficit: p(11),
            }
        })
        .collect()
}

fn run(case: &Case) -> BurnLoss {
    let speed = libm::sqrt(MU / case.radius);
    let (c, s) = (libm::cos(case.angle), libm::sin(case.angle));
    let initial = Keyframe {
        time: 0.0,
        position: [case.radius * c, case.radius * s, 0.0],
        velocity: [-speed * s, speed * c, 0.0],
        mass: case.mass,
    };
    let burn = Burn {
        start: 0.0,
        end: case.duration,
        force_newtons: [0.0, case.thrust, 0.0],
        specific_impulse_seconds: case.isp,
    };
    let options = Options {
        relative_tolerance: 1e-12,
        absolute_tolerance: 1e-12,
        initial_step: 1.0,
        max_step: 5.0,
        max_steps: 1_000_000,
    };
    let (_, loss) = isolate_finite_burn(initial, case.duration, options, MU, &[burn]).unwrap();
    assert!(
        loss.identity_residual_m_s.abs() < 1e-6,
        "{} identity residual {}",
        case.name,
        loss.identity_residual_m_s
    );
    loss
}

#[test]
fn oracle_finite_burn_loss_isolated_within_one_percent() {
    for case in cases() {
        let loss = run(&case);
        let rel = |a: f64, b: f64| (a - b).abs() / b.abs().max(1e-12);
        assert!(
            rel(loss.ideal_delta_v_m_s, case.ideal) < 0.01,
            "{} ideal {} vs {}",
            case.name,
            loss.ideal_delta_v_m_s,
            case.ideal
        );
        assert!(
            rel(loss.steering_loss_m_s, case.steering) < 0.01,
            "{} steering {} vs {}",
            case.name,
            loss.steering_loss_m_s,
            case.steering
        );
        assert!(
            rel(loss.gravity_loss_m_s, case.gravity) < 0.01,
            "{} gravity {} vs {}",
            case.name,
            loss.gravity_loss_m_s,
            case.gravity
        );
        assert!(
            rel(loss.speed_deficit_m_s, case.deficit) < 0.01,
            "{} deficit {} vs {}",
            case.name,
            loss.speed_deficit_m_s,
            case.deficit
        );
        println!(
            "{}: steer={:.9} (ref {:.9}), gravity={:.9} (ref {:.9}), deficit={:.9} (ref {:.9})",
            case.name,
            loss.steering_loss_m_s,
            case.steering,
            loss.gravity_loss_m_s,
            case.gravity,
            loss.speed_deficit_m_s,
            case.deficit
        );
    }
}

#[test]
fn short_centered_burn_matches_card_cubic_estimate_within_one_percent() {
    let case = cases()
        .into_iter()
        .find(|c| c.name == "short_perigee")
        .unwrap();
    let loss = run(&case);
    let estimate =
        BurnLoss::centered_periapsis_estimate(case.delta_v, MU, case.radius, case.duration);
    let rel = (loss.steering_loss_m_s - estimate).abs() / estimate;
    assert!(
        rel < 0.01,
        "estimate {estimate}, exact {}, rel {rel}",
        loss.steering_loss_m_s
    );
}

#[test]
fn low_twr_tli_initial_acceleration_is_zero_point_eight() {
    let case = cases()
        .into_iter()
        .find(|c| c.name == "low_twr_tli")
        .unwrap();
    assert!((case.thrust / case.mass - 0.8).abs() < 1e-12);
    // The long burn sweeps far beyond the small-angle regime, so the cubic
    // estimate must NOT be used as its oracle.
    let sweep = libm::sqrt(MU / case.radius.powi(3)) * case.duration;
    assert!(sweep > 1.0, "sweep {sweep} rad");
}
